using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // --- AddItem tests ---

    [TestMethod]
    public void AddItem_SingleItem_DoesNotThrow()
    {
        _cart.AddItem("SKU001", 1, 9.99m);
    }

    [TestMethod]
    public void AddItem_MultipleItems_DoesNotThrow()
    {
        _cart.AddItem("SKU001", 2, 5.00m);
        _cart.AddItem("SKU002", 1, 12.50m);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_DoesNotThrow()
    {
        _cart.AddItem("SKU001", 1, 10.00m);
        _cart.AddItem("SKU001", 3, 10.00m);
    }

    // --- RemoveItem tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_DoesNotThrow()
    {
        _cart.AddItem("SKU001", 1, 5.00m);
        _cart.RemoveItem("SKU001");
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_DoesNotThrow()
    {
        _cart.RemoveItem("NOSUCHSKU");
    }

    // --- CalculateTotal tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsPriceTimesQuantity()
    {
        _cart.AddItem("SKU001", 3, 10.00m);
        var total = _cart.CalculateTotal();
        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAllItems()
    {
        _cart.AddItem("SKU001", 2, 5.00m);
        _cart.AddItem("SKU002", 1, 12.50m);
        var total = _cart.CalculateTotal();
        Assert.AreEqual(22.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _cart.AddItem("SKU001", 2, 5.00m);
        _cart.AddItem("SKU002", 1, 12.50m);
        _cart.RemoveItem("SKU001");
        var total = _cart.CalculateTotal();
        Assert.AreEqual(12.50m, total);
    }

    // --- ApplyCoupon tests ---

    [TestMethod]
    public void ApplyCoupon_ValidCode_DoesNotThrow()
    {
        _cart.AddItem("SKU001", 1, 50.00m);
        _cart.ApplyCoupon("SAVE10");
    }

    [TestMethod]
    public void ApplyCoupon_ReducesTotal()
    {
        _cart.AddItem("SKU001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, "Total should be reduced after applying coupon.");
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsException()
    {
        _cart.AddItem("SKU001", 1, 50.00m);
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("INVALIDCODE"));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_DoesNotThrow()
    {
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }
}

